import React, { useState, useRef, useMemo, useCallback, memo } from "react";

var APP_VERSION = "v1.0.17004";
// v1.0.10199 (per Mike, 8/2/26): real logo, embedded as base64 data URIs directly in the file.
// No external URL, no filesystem path — both were tried before and both failed in the artifact
// sandbox (blocked cross-origin fetch, no local file access). Baking the image data into the
// file itself sidesteps both restrictions and works identically once this becomes the real
// Electron desktop app. Background was pure black in the source PNG, so it was chroma-keyed to
// transparent (smooth alpha ramp, not a hard cutout) so it reads correctly in both dark mode and
// the lighter theme, instead of carrying its own black box around it.
var LOGO_FULL_DATA_URI="data:image/png;base64,";
var LOGO_WORDMARK_DATA_URI="data:image/png;base64,";
// v1.0.10200 (per Mike, 8/2/26): light-mode variant — his own logo file, background this time
// was white instead of black, so it needed the opposite chroma-key (keying out near-white
// pixels instead of near-black) to get a clean transparent version for the lighter theme.
var LOGO_FULL_DATA_URI_LIGHT="data:image/png;base64,";
var LOGO_WORDMARK_DATA_URI_LIGHT="data:image/png;base64,";

// Flip to true to re-enable the debug tools that cracked two real bugs on 7/12/26 (fetch
// counter/timestamp — confirmed whether a fetch fired at all, cracked the daisy-chain bug; raw
// genre debug line — confirmed what the model actually returned, cracked the +8 genre problem).
// Leave false for normal use. Nothing else needs to change — this one flag controls both.
var DEBUG_MODE = false;

