var _recCache = {};
function getCacheKey(fname,vibeOff,energyOff){return fname+"|v"+vibeOff+"|e"+energyOff;}
function cacheGet(fname,vibeOff,energyOff){return _recCache[getCacheKey(fname,vibeOff,energyOff)]||null;}
function cacheSet(fname,vibeOff,energyOff,results){_recCache[getCacheKey(fname,vibeOff,energyOff)]=results;}

// ─────────────────────────────────────────────
// SESSION HISTORY — silent logging + exportable log
// Each entry: {id, ts, seed:{name,bpm,key,genre}, vibeOffset, energyOffset, results:[{name,bpm,key,genre,year,outcome}], note}
// outcome per result: "dragged" | "up" | "down" | "prepared" | "ignored" | "shown"
// ─────────────────────────────────────────────
var HISTORY_KEY="cheatcode_session_history";
var PREFS_KEY="cheatcode_user_prefs";
var ARTIST_ERA_CACHE_KEY="cheatcode_artist_era_cache";
// v1.0.16008 (per Mike, 8/17/26): staleness tracking grows forever with no ceiling — every build
// of the same exact prompt just keeps adding to the exclusion set indefinitely. Since context
// sampling for a build tops out around 800 candidate tracks, an unbounded exclusion list for a
// narrow/niche prompt run repeatedly enough will eventually exhaust most of its realistic
// candidate pool within that 800-sample window. Mike's call: auto-reset a prompt's exclusion set
// once it reaches 200 entries, well under the 800 ceiling, so there's always a healthy pool of
// genuinely fresh candidates rather than riding it all the way down to the safety-valve fallback.
var CRATE_STALE_CAP=200;
var resetIfOverCap=function(existing){return(existing&&Object.keys(existing).length>=CRATE_STALE_CAP)?{}:(existing||{});};
var TITLE_ERA_CACHE_KEY="cheatcode_title_era_cache";
var LOCAL_BACKUP_KEY="cheatcode_history_backup_v1";
function makeHistoryId(){return"h_"+Date.now()+"_"+Math.random().toString(36).slice(2,8);}
function makeSessionId(){return"sess_"+Date.now()+"_"+Math.random().toString(36).slice(2,8);}

