function inferArtistEra(trackName){
  var at=getArtistTitle(trackName);
  var artist=(at.artist||trackName).toLowerCase().trim();
  if(DYNAMIC_ARTIST_ERA_CACHE[artist])return DYNAMIC_ARTIST_ERA_CACHE[artist];
  if(ARTIST_ERA_MAP[artist])return ARTIST_ERA_MAP[artist];
  // v1.0.13265 (per Mike, 8/8/26): CONFIRMED real bug — 8 map entries have periods (Dr. Dre,
  // Mary J. Blige, R. Kelly, T.I., will.i.am, J. Cole, H.E.R., notorious b.i.g.), and none of them
  // match if the actual library file just says "Dr Dre" or "Notorious BIG" without the periods —
  // which is almost certainly how they're really tagged. That's exactly why "Big Poppa" kept
  // surviving the era filter: inferArtistEra silently returned 0 for it, so the tag-vs-artist-era
  // correction had nothing to compare against and never fired. Stripping periods from both sides
  // before comparing fixes every affected entry at once instead of patching each one by hand.
  var artistNoDots=artist.replace(/\./g,"");
  for(var key in ARTIST_ERA_MAP){
    var keyNoDots=key.replace(/\./g,"");
    // v1.0.13265 follow-up: stripping periods turned "T.I." into "ti" and "H.E.R." into "her" —
    // both dangerously short, common substrings. "Christina Aguilera" contains "ti", "Cher"
    // contains "her" — both were falsely matching before this guard. Requiring 4+ characters on
    // the stripped key keeps the fix for the legitimately safe entries (Notorious BIG, Dr Dre,
    // Mary J Blige, R Kelly, J Cole, will i am) without reintroducing false positives on short
    // acronym-style names. An exact match (periods intact) above still works for T.I./H.E.R.
    // regardless — this guard only affects the loose no-punctuation fallback.
    if(keyNoDots.length<4)continue;
    if(artistNoDots.indexOf(keyNoDots)!==-1||keyNoDots.indexOf(artistNoDots)!==-1)return ARTIST_ERA_MAP[key];
  }
  // v1.0.13273 (per Mike, 8/8/26): the DJ PS1 / SERAFIN / edit-producer fix. When the credited
  // "artist" isn't a real recording artist at all — it's the person who made the edit — none of
  // the above will ever match, correctly. This is the final fallback: check whether the
  // title-based resolver found a real artist name embedded in THIS SPECIFIC track's title, since
  // the same edit-producer credit sits on many unrelated songs and can't be resolved as if it
  // were one person with one era.
  var titleKey=getRawTitleFromName(trackName);
  if(titleKey&&DYNAMIC_TITLE_ERA_CACHE[titleKey])return DYNAMIC_TITLE_ERA_CACHE[titleKey];
  return 0;
}
