function SliderRow(props){var ia=props.ia;var grayColor=props.grayColor||GRAY;var handleTrackClick=function(e){var rect=e.currentTarget.getBoundingClientRect();var pct=(e.clientX-rect.left)/rect.width;pct=Math.max(0,Math.min(1,pct));var val=Math.round(props.min+pct*(props.max-props.min));props.onChange(val);};return(<div style={{flex:1,minWidth:0}}><LabelBox accent={props.accent} line1={props.line1||null} line2={props.line2||null} grayColor={grayColor}/><div style={{position:"relative",padding:"8px 0"}}><div style={{position:"absolute",top:"50%",left:0,right:0,height:2,background:ia(0.35),borderRadius:2,transform:"translateY(-50%)"}}/><div style={{position:"absolute",top:"50%",left:"50%",width:1,height:10,background:ia(0.6),transform:"translateY(-50%)"}}/><input type="range" min={props.min} max={props.max} step={1} value={props.value} onChange={function(e){props.onChange(parseInt(e.target.value));}} onClick={handleTrackClick} style={{width:"100%",appearance:"none",WebkitAppearance:"none",background:"transparent",cursor:"pointer",position:"relative",zIndex:1,margin:0,padding:0,height:20}}/></div><div style={{display:"flex",justifyContent:"space-between",marginTop:2}}><span style={{fontSize:11,fontFamily:"Arial,sans-serif",color:grayColor,fontWeight:600}}>{props.leftLabel}</span><span style={{fontSize:11,fontFamily:"Arial,sans-serif",color:grayColor,fontWeight:600}}>{props.rightLabel}</span></div></div>);}

var VIBE_LABELS={"-8":["Vibe Lock","Exact subgenre and style — strictest possible"],"-7":["Style Lock","Same subgenre only, strict match"],"-6":["Subgenre Lock","Same subgenre plus one level broader"],"-5":["Genre Wall","Hard filter on — no genre crossover"],"-4":["Subgenres OK","Primary genre family, adjacent subgenres allowed"],"-3":["Same Era, Same Feel","Same genre plus immediate neighbors only"],"-2":["Genre Priority","Mostly same genre, light drift if era matches"],"-1":["Genre First","Genre is still top priority, slight wandering allowed"],"0":null,"1":["Neighboring Vibe","Blend in exactly 1 genre outside the seed's"],"2":["Genre Bleed","Blend in exactly 2 genres outside the seed's"],"3":["Cross Pollinate","Blend in exactly 3 genres outside the seed's"],"4":["Genre Mashup","Blend in exactly 4 genres outside the seed's"],"5":["No Limits","No genre restriction — anything goes"],"6":["Anything Goes","No genre restriction — anything goes (same as +5 for now — reserved for future tuning)"],"7":["Wide Open","No genre restriction — anything goes (same as +5 for now — reserved for future tuning)"],"8":["Total Chaos","No genre restriction — anything goes (same as +5 for now — reserved for future tuning)"]};

function DualSliders(props){var energyOffset=props.energyOffset,setEnergyOffset=props.setEnergyOffset,vibeOffset=props.vibeOffset,setVibeOffset=props.setVibeOffset,accent=props.accent,ia=props.ia,sliderLabelColor=props.sliderLabelColor;var energyLine1=energyOffset===0?null:energyOffset>0?"Build It Up":"Bring It Down";var energyLine2=energyOffset===0?null:(energyOffset>0?"+":"")+energyOffset;var vibeEntry=VIBE_LABELS[String(vibeOffset)]||null;return(<div style={{display:"flex",gap:16,marginBottom:"1rem",alignItems:"flex-start"}}><SliderRow value={energyOffset} min={-16} max={16} onChange={setEnergyOffset} leftLabel="-16" rightLabel="+16" line1={energyLine1} line2={energyLine2} accent={accent} ia={ia} grayColor={sliderLabelColor}/><div style={{width:1,background:ia(0.3),alignSelf:"stretch",marginTop:38}}/><SliderRow value={vibeOffset} min={-8} max={8} onChange={setVibeOffset} leftLabel="Genre Lock" rightLabel="Flip Genre" line1={vibeEntry?vibeEntry[0]:null} line2={vibeEntry?vibeEntry[1]:null} accent={accent} ia={ia} grayColor={sliderLabelColor}/></div>);}
