function SortHeader(props){var field=props.field,label=props.label,sortField=props.sortField,sortDir=props.sortDir,onSort=props.onSort,accent=props.accent,active=sortField===field;return <button onClick={function(){onSort(field);}} style={{background:"none",border:"none",cursor:"pointer",fontSize:10,fontWeight:700,color:active?accent:GRAY,letterSpacing:"0.08em",textTransform:"uppercase",padding:"4px 6px",display:"flex",alignItems:"center",gap:3}}>{label}<span style={{fontSize:8}}>{active?(sortDir==="asc"?"▲":"▼"):"⬍"}</span></button>;}

