  // v1.0.13248 (per Mike, 8/8/26): the actual crash-catching mechanism — runs once on mount.
  // Wraps console.error/warn to keep a rolling buffer (last 50), and listens for both uncaught
  // thrown errors and unhandled promise rejections, since a rejected fetch/API call is just as
  // real a "something broke" as a thrown error and shouldn't be missed.
  React.useEffect(function(){
    var origError=console.error,origWarn=console.warn;
    var pushBuf=function(level,args){
      try{
        var msg=Array.prototype.map.call(args,function(a){try{return typeof a==="string"?a:JSON.stringify(a);}catch(e){return String(a);}}).join(" ");
        consoleBufferRef.current.push({level:level,msg:msg,t:Date.now()});
        if(consoleBufferRef.current.length>50)consoleBufferRef.current.shift();
      }catch(e){}
    };
    console.error=function(){pushBuf("error",arguments);origError.apply(console,arguments);};
    console.warn=function(){pushBuf("warn",arguments);origWarn.apply(console,arguments);};
    var onError=function(e){
      setCapturedError({message:e.message||"Unknown error",stack:(e.error&&e.error.stack)||"",t:Date.now()});
      setShowErrorReport(true);
    };
    var onRejection=function(e){
      var reason=e.reason;
      setCapturedError({message:"Unhandled promise rejection: "+(reason&&reason.message?reason.message:String(reason)),stack:(reason&&reason.stack)||"",t:Date.now()});
      setShowErrorReport(true);
    };
    window.addEventListener("error",onError);
    window.addEventListener("unhandledrejection",onRejection);
    return function(){
      console.error=origError;console.warn=origWarn;
      window.removeEventListener("error",onError);
      window.removeEventListener("unhandledrejection",onRejection);
    };
  },[]);

  // v1.0.13248 (per Mike, 8/8/26): report generation — explicit exclusions honored: no music
