      fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},signal:controller?controller.signal:undefined,body:JSON.stringify({model:"claude-sonnet-5",max_tokens:dynamicMaxTokens,system:"You are a DJ assistant. Return ONLY a valid JSON array of exactly "+requestCount+" objects: [{id,name,bpm,key}]. No markdown, no extra text. Library: ID|DisplayName|BPM|Key|PlayCount|Year|Genre."+styleProfileLine+crateVibePromptLine+doPlayLine+doNotPlayLine+diversityLine+" PRIORITY: 1) Genre, 2) BPM, 3) Key. "+bpmLine+playCountLine+artistScopeLine+" No duplicates.",messages:[{role:"user",content:"Library:\n"+ctx.context+"\n\nVibe: "+prompt+"\n\nReturn exactly "+requestCount+" tracks matching this vibe."}]})})
