  var tabStyle=function(a){return{background:"none",border:"none",borderBottom:a?"2px solid "+accent:"2px solid transparent",padding:"10px 14px",cursor:"pointer",fontSize:11,fontWeight:a?700:400,color:a?accent:GRAY,marginBottom:-1,letterSpacing:"0.08em",textTransform:"uppercase",transition:"color 0.15s"};};
  var sizeBtnStyle=function(a){return{fontSize:13,fontWeight:a?700:400,padding:"6px 16px",background:a?accent:"transparent",color:a?bg:GRAY,border:"1px solid "+(a?accent:ia(0.4)),borderRadius:6,cursor:"pointer",transition:"all 0.15s"};};
  var buildBtnStyle=function(d){return{fontSize:13,fontWeight:700,padding:"10px 28px",background:d?"#2a2a2a":accent,color:d?"#888":bg,border:d?"1px solid #444":"none",borderRadius:8,cursor:d?"not-allowed":"pointer",letterSpacing:"0.08em",textTransform:"uppercase",transition:"all 0.15s"};};
  var goBtnStyle=function(d){return{padding:"0 18px",height:48,borderRadius:10,border:d?"1px solid #444":"none",cursor:d?"not-allowed":"pointer",background:d?"#2a2a2a":accent,color:d?"#888":bg,fontSize:13,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.06em",whiteSpace:"nowrap",transition:"all 0.15s"};};
  var shProps={sortField:sortField,sortDir:sortDir,onSort:handleSort,accent:accent};
  var sectionLbl={fontSize:10,color:GRAY,textTransform:"uppercase",letterSpacing:"0.12em",fontWeight:700,margin:"0 0 12px"};
  var glowSweepStyle=useMemo(function(){return{backgroundImage:"linear-gradient(90deg,"+accentAlpha(0.3)+" 0%,"+accent+" 40%,#fff 50%,"+accent+" 60%,"+accentAlpha(0.3)+" 100%)",backgroundSize:"200% auto",animation:"glowSweep 2s linear infinite",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text",fontSize:13,fontWeight:700,letterSpacing:"0.12em",textTransform:"uppercase"};},[accent,accentAlpha]);

  var ResHeader=function(){return(<div style={{display:"flex",alignItems:"center",padding:"4px 14px",background:"rgba(0,0,0,0.5)",borderBottom:"1px solid "+accentAlpha(0.15),gap:10}}><div style={{flex:1}}><SortHeader field="name" label="Artist / Title" {...shProps}/></div><SortHeader field="bpm" label="BPM" {...shProps}/><SortHeader field="key" label="Key" {...shProps}/><div style={{width:80,flexShrink:0}}/></div>);};
  var CrateHeader=function(){return(<div style={{display:"flex",alignItems:"center",padding:"4px 14px",background:"rgba(0,0,0,0.5)",borderBottom:"1px solid "+accentAlpha(0.15),gap:10}}><div style={{width:20,flexShrink:0}}/><div style={{flex:1}}><SortHeader field="name" label="Artist / Title" {...shProps}/></div><SortHeader field="bpm" label="BPM" {...shProps}/><SortHeader field="key" label="Key" {...shProps}/></div>);};
  var EmptyLib=function(){return(<div style={{textAlign:"center",padding:"4rem 2rem",borderRadius:12,background:"#2a2a2a",border:"1px solid "+accentAlpha(0.25)}}><div style={{fontSize:48,marginBottom:16}}>📁</div><p style={{fontSize:16,fontWeight:700,color:WHITE,margin:"0 0 8px"}}>No Library Loaded</p><p style={{fontSize:13,color:GRAY,margin:"0 0 1.5rem",lineHeight:1.5}}>Import your DJ library before continuing.</p><button onClick={function(){setTab(3);}} style={{padding:"10px 24px",borderRadius:8,border:"none",cursor:"pointer",background:accent,color:"#000",fontSize:13,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.08em"}}>Go To Library →</button></div>);};

