      {showRating&&<RatingModal accent={accent} accentAlpha={accentAlpha} onRate={function(r){setHasRatedEver(true);setShowRating(false);checkPostSessionNudge(r);}} onNotNow={function(){setRatingNotNowDate(Date.now());setShowRating(false);}} onNeverAskAgain={function(){setNeverAskAgain(true);setShowRating(false);}}/>}
