                  {!isSearching&&<button onClick={function(){if(searchSeedTrack)fetchSearchResults(searchSeedTrack);else fetchBangerResults(bangerTrack,bangerExcluded,votes,bangerResults,draggedFromBatch,true,true);}} style={{fontSize:12,padding:"4px 10px",background:"transparent",border:"2px solid "+accentAlpha(0.3),borderRadius:6,color:accent,cursor:"pointer",letterSpacing:"0.04em",fontWeight:700}}>Try Again</button>}
