                              <button onClick={function(e){e.stopPropagation();simulateDeckDrop(deckNum);}} style={{marginTop:6,fontSize:9,padding:"3px 8px",borderRadius:5,border:"1px solid "+ia(0.3),background:"transparent",color:GRAY,cursor:"pointer",letterSpacing:"0.04em"}}>Simulate Drop</button>
