                        {activeResults.map(function(t,i){return <ResultRow key={t.name} t={t} vote={votes[t.name]||null} isPrepared={prepareList.has(t.name)} accent={accent} rowBg={i%2===0?rowEven:rowOdd} borderCol={borderCol} bpmBorder={bpmBorder} handleVote={handleVote} handleResultDragStart={handleResultDragStart} handleLikeAsSeed={handleLikeAsSeed}/>;})}
